		array( '27 сәуір', '«Кедентранссервис» АҚ Директорлар кеңесінің сырттай отырысы өткізіліп, онда:<br>- «Кедентранссервис» АҚ және оның еншілес ұйымының 2016 жылға арналған қызметі нәтижелерінің есебі бекітілді;<br>- «Кедентранссервис» АҚ 2016 жылдың 31 желтоқсанында аяқталған жылға арналған жылдық қаржы (с.і. шоғырландырылған және бөлек) есептілігі алдын ала бекітілді;<br>- «Кедентранссервис» АҚ Беларусь Республикасының Брест қ. өкілеттілігінің ашылуы туралы шешім қабылданды;<br>- «Кедентранссервис» АҚ Стратегиялық жоспарлау жөніндегі комитет мүшесі Елубаев Санжар Бақытұлы сайланды;<br>- «Кедентранссервис» АҚ Басқарма мүшесі Оразалин Нұрлан Жабайұлы өкілдігінің мерзімнен бұрын тоқтатылуы және «Кедентранссервис» АҚ Басқарма мүшесі болып Исмұхамбетова Назым Тоқтамысқызын сайлау туралы шешімі қабылданды;<br>- жасалуында қызығушылық бар бірқатар мәмілелерді жасау туралы шешімі қабылданды.' ),
		array( '26 маусым', 'Директорлар кеңесінің шешімдері:<br>2015 жылдың 26 маусымы күні Қоғамның Директорлар кеңесінің отырысы (күндізгі дауыс беру түрінде) өткізіліп, онда қабылданды:<br>— «Кедентранссервис» АҚ Директорлар кеңесінің төрағасы ретінде Алпысбаев Қанат Қалиұлын сайлау туралы шешімі қабылданды;<br>— «Кедентранссервис» АҚ Директорлар кеңесінің 2016 жылы өткізілетін акционерлердің жылдық жалпы жиналысына дейінгі мерзімге арналған Жұмыс жоспары бекітілді;<br>1. 6 адам көлемінде Стратегиялық жоспарлау жөніндегі комитеттің;<br>2. 5 адам көлемінде Аудит жөніндегі комитеттің;<br>3. 4 адам көлемінде Кадрлар, сыйақылар және әлеуметтік сұрақтар жөніндегі комитеттің.<br>— сандық құрамы анықталды;<br>— «Кедентранссервис» АҚ Стратегиялық жоспарлау жөніндегі комитеттің құрамына төмендегідей тұлғаларды сайлау туралы шешімі қабылданды:<br>1) Лопатин Антон Викторовичті;<br>2) Цветков Дмитрий Александровичті;<br>3) Жемчугов Андрей Сергеевичті;<br>4) Сұлтанов Арман Тұрлыханұлын;<br>5) Мәдиева Сәуле Едімтайқызын;<br>6) Бекмағамбетов Мұрат Маратұлын.<br>— Стратегиялық жоспарлау жөніндегі комитеттің төрағасы ретінде Лопатин Антон Викторовичті сайлау туралы шешім қабылданды.<br>— «Кедентранссервис» АҚ Аудит жөніндегі комитеттің құрамында төмендегідей тұлғаларды сайлау туралы шешім қабылданды:<br>1) Дружинин Алексей Александровичті;<br>2) Калмыков Константин Сергеевичті;<br>3) Устинова Елена Владимировнаны;<br>4) Станкова Елена Борисовнаны;<br>5) Бимахимова Раушан Сембекқызын.<br>— Аудит жөніндегі комитеттің төрағасы ретінде Дружинин Алексей Александровичті сайлау туралы шешімі қабылданды.<br>— «Кедентранссервис» АҚ Кадрлар, сыйақылар және әлеуметтік сұрақтар жөніндегі комитеттің құрамына төмендегідей тұлғаларды сайлау туралы шешім қабылданды:<br>1) Құрманов Жолдасбек Есенбайұлын;<br>2) Исмаилова Сания Көшкінбайқызын;<br>3) Гончаров Михаил Робертовичті;<br>4) Строкова Елена Юрьевнаны.<br>— Кадрлар, сыйақылар және әлеуметтік сұрақтар жөніндегі комитеттің төрағасы ретінде Құрманов Жолдасбек Есенбайұлын сайлау туралы шешімі қабылданды.<br>— Жасалуында қызығушылық бар бірқатар мәмілелерді жасау туралы шешімі қабылданды:<br>1. «Кедентранссервис» АҚ мен «Қазақстан темір жолы» Ұлттық компаниясы» АҚ арасында 2014 жылдың 31 желтоқсанында жасалған № 332/88/А Мүліктік жалға беруге ұсыну бойынша қызметтерді сатып алу шартына 07.07.2015 ж. № 117/260 Қосымша келісімін жасау туралы.<br>2. «Қазтеміртранс» АҚ Семей филиалы мен «Кедентранссервис» АҚ Шығыс Қазақстан облысы бойынша филиалы арасында 26.06.2015 ж. жасалған № 26–06/1-НПФ-6 Кірме жолдарды пайдалану қызметтерін көрсету шартын жасау туралы.<br>3. «Қазақстан темір жолы» Ұлттық компаниясы» АҚ филиалы, Ақтөбе жол бөлімшесі мен «Кедентранссервис» АҚ Батыс Қазақстан өңірлік филиалы арасында 26.06.2015 ж. жасалған № 255/ПРР Тиеу-түсіру жұмыстары жөніндегі қызметтерді сатып алу шартын жасау туралы.<br>4. «Қазақстан темір жолы» Ұлттық компаниясы» АҚ филиалы Қарағанды жол бөлімшесі мен «Кедентранссервис» АҚ Қарағанды облысы бойынша филиалы арасында 26.06.2015 ж. жасалған № 67 Тиеу-түсіру жұмыстары жөніндегі қызметтерді сатып алу шартын жасау туралы.<br>5. «Кедентранссервис» АҚ мен «Центр по перевозке грузов в контейнерах «ТрансКонтейнер» КАҚ арасында 29.06.2015 ж. жасалған № 83/5-р «Центр по перевозке грузов в контейнерах «ТрансКонтейнер» КАҚ меншігіндегі жылжымалы құрамның және ірітонналы контейнерлерінің ағымдағы жөндеу жұмыстарын жүргізуді ұйымдастыру жөніндегі агенттік шартын жасау туралы.<br>6. «Кедентранссервис» АҚ мен «Қазтранссервис» АҚ арасында 2012 жылдың 30 қазанында жасалған № 246-АО/143/4-А Мүліктік жалға алу шартына 07.07.2015 ж. № 246-АО/143/4-А-85/2-А-85/1-Р Қосымша келісімін жасау туралы.<br>7. «Қазтранссервис» АҚ мен «Кедентранссервис» АҚ арасында 2015 жылдың 31 желтоқсанында жасалған № КТС/07-А/174/37-А Мүліктік жалға алу шартына 23.06.2015 ж. № 174/34-А/81/23-А Қосымша келісім жасау туралы.<br>8. «Қазтеміртранс» АҚ мен «Кедентранссервис» АҚ арасында 2015 жылдың 29 қаңтарында жасалған № 29–01/5-НПФО/а/174/37-А Мүліктік жалға алу шартына 29.06.2015 ж. № 174/37-А/83/4-А Қосымша келісім жасау туралы.<br>9. «Кедентранссервис» АҚ мен «Қазтранссервис» АҚ арасында 02.10.2014 ж. жасалған № 126/10-ПД/КТС/37-п «Центр по перевозке грузов в контейнерах «ТрансКонтейнер» КАҚ меншігіндегі ірітонналы контейнерлердің ағымдағы жөндеу жұмыстарын атқару шартына 08.06.2015 ж. № 126\\10–74/2-ПД/1 Қосымша келісімін жасау туралы.' ),
		array( '8 қаңтар', '"Кедентранссервис" АҚ Директорлар кеңесінің сырттай отырысы өтті, онда жасалуына мүдделілік бар мәмілені жасасу туралы шешім қабылданды.<br>2016 жылғы 04 Ақпанда "Қазақстан Республикасы Әділет министрлігі Астана қаласы Әділет департаментінің Есіл аумақтық бөлімі" республикалық мемлекеттік мекемесінің сот актілерін орындау филиалының сот орындаушысының қаулысымен 7 020 214 теңге сомасында ақшалай қаражатқа тыйым салынды.<br>2016 жылғы 10 ақпанда "Кедентранссервис" АҚ Директорлар кеңесінің сырттай отырысы өтті, онда:<br>- "Кедентранссервис" АҚ акционерлерінің кезектен тыс жалпы жиналысын шақыру және күн тәртібін қалыптастыру туралы шешім қабылданды»;<br>- жасалуына мүдделілік бар бірқатар мәмілелер жасасу туралы шешім қабылданды.' ),
