	'2019' => array(
		array( '27 желтоқсан', '"Кедентранссервис" АҚ Жалғыз акционерінің шешімімен:<br>- жасалуына мүдделілік бар мәмілелер болып табылатын "Кедентранссервис" АҚ мен "Қазақстанның көлік холдингі" ЖШС арасында мүліктік жалдау (жалға алу) шарттарын жасасу туралы шешім қабылданды.<br>- "Кедентранссервис" АҚ Директорлар кеңесінің әрекет етуші құрамының өкілеттік мерзімі 2020 жылғы 31 желтоқсанға дейін ұзартылды.<br>- "Кедентранссервис" АҚ Директорлар кеңесі туралы ереже бекітілді.' ),
		array( '27 тамыз', '«Кедентранссервис» АҚ Жалғыз акционерінің шешімімен «Кедентранссервис» АҚ мен «Транспортный холдинг Казахстана» ЖШС арасында жасалған іске асырылуында мүдделілік бар мәміле болып табылатын өтеусіз пайдалану шартына қосымша келісім жасасу туралы шешім қабылданды.' ),
		array( '24 мамыр', '«Кедентранссервис» АҚ Жалғыз акционерінің шешімімен:<br>- 2018 жылдың 31 желтоқсанында аяқталған жыл үшін «Кедентранссервис» АҚ-ның жылдық (оның ішінде шоғырландырылған және жеке) қаржылық есептілігі бекітілді.<br>- «Кедентранссервис» АҚ-ның 2017 жылғы таза табысын бөлу тәртібі бекітілді.<br>- «Кедентранссервис» АҚ акционерлеріне 2017 жылдың қорытындысы бойынша дивидендтер төлеу туралы шешім қабылданды.<br>- «Кедентранссервис» АҚ бір жай акциясына 3 302 тенге 80 тиын дивиденд мөлшері бекітілді.<br>- дивидендтерді төлеу нысаны анықталды - ақшалай.<br>- дивидендтерді төлеу тәртібі анықталды – «Кедентранссервис» АҚ Жалғыз акционерінің банк шотына аудару арқылы ақшасыз есеп айырысу<br>- дивидендтерді төлеудің басталу күні анықталды – «Кедентранссервис» АҚ Жалғыз акционері дивидендтер төлеу туралы шешім қабылдағаннан кейінгі келесі күн.' ),
		array( '23 сәуір', '«Кедентранссервис» АҚ Директорлар кеңесінің шешімімен:<br>- «Кедентранссервис» АҚ Басқарма мүшесі Назым Токтамысовна Исмухамбетованың өкілеттігі мерзімінен бұрын тоқтатылды.<br>- «Кедентранссервис» АҚ Басқарма құрамына Калмухан Сапаргалиевич Тапалов сайланды.' ),
