	'2016' => array(
		array( '6 қаңтар', 'Қоғамның Директорлар кеңесінің сырттай отырыстарында 2015 жылдың 23 және 24 желтоқсан күндері қабылданған шешімдер. 2015 жылдың 23 желтоқсаны күні «Кедентранссервис» АҚ Директорлар кеңесінің сырттай отырысы өткізіліп, оның барысында жасалуында қызығушылық бар бірқатар мәмілелерді жасау туралы шешімі қабылданды.<br>2015 жылдың 24 желтоқсаны күні «Кедентранссервис» АҚ Директорлар кеңесінің сырттай отырысы болып өтті. Онда:<br>— «Кедентранссервис» АҚ және оның еншілес ұйымының 2015 жылдың 9 айына арналған қызметінің қорытындыларына қатысты есеп бекітілді;<br>— «Кедентранссервис» АҚ филиал жүйесінің ұйымдастырушылық құрылымын қайта құру туралы, ақпараты назарға алынды;<br>— «Кедентранссервис» АҚ қатысуымен 2015 жылдың 9 айына арналған сот дауларына қатысты жағдай және оны қарау барысы туралы, ақпараты назарға алынды;<br>— «Кедентранссервис» АҚ Басқармасының мүшелері Б. Ж. Байкарин мен Д.А.Әубәкіровтың өкілдіктері мерзімнен бұрын тоқтатылды;<br>— «Кедентранссервис» АҚ Басқармасының мүшелері болып Н. Ж. Оразалин мен Г.К.Мұқанов сайланды;<br>— «Кедентранссервис» АҚ Қызметтік құпиясын құрайтын, ақпарат тізімі бекітілді;<br>— Жасалуында қызығушылық бар мәмілелерді жасау туралы шешімі қабылданды.' ),
		array( '25 ақпан', 'Директорлар кеңесінің шешімдері:<br>— «Кедентранссервис» АҚ 2013, 2014 және 2015 жылдың І жартыжылдығына арналған қаржы-шаруашылық қызметін тексеру қорытындылары туралы, ақпарат назарға алынды.<br>— «Кедентранссервис» АҚ 2013, 2014 және 2015 жылдың І жартыжылдығына арналған қаржы-шаруашылық қызметін тексеру барысында анықталған бұзуларды жоюға қатысты Шаралар жоспары бекітілді.<br>— «Кеденстранссервис» АҚ 2015 жылдың 4 тоқсанына арналған тәуекелдер тізілімінің сыни тәуекелдері туралы есебі назарға алынды.<br>— «Кедентранссервис» АҚ Ішкі аудит қызметінің 2015 жылға арналған атқарылған жұмыс туралы есебі назарға алынды.<br>— «Кедентранссервис» АҚ 2015 жылға арналған дебиторлық қарызын төлету бойынша өткізілген сот жұмысы туралы, ақпараты назарға алынды.<br>— «Кедентранссервис» АҚ Директорлар кеңесі туралы Ережесіне өзгертулер мен толықтырулар жобасы мақұлданды.<br>— «Кедентранссервис» АҚ 2016 жылға арналған тиімділіктің басты көрсеткіштерінің деңгейлі және мақсатты-деңгейлері, тізімі бекітілді.<br>— Тараптардың келісімі бойынша еңбек келісімшартын бұзуға орай «Кедентранссервис» АҚ Вице-президентінің қызметінен Ю. В. Сукмановты босату келісілді және Басқарма мүшесі ретінде оның өкілдіктері тоқтатылды.<br>— «Кедентранссервис» АҚ Вице-президентінің қызметіне Е. Р. Кулаковтың кандидатурасы келісілді.<br>— «Кедентранссервис» АҚ Демеушілік және қайырымдылық көмек көрсету ережелеріне өзгертулер енгізілді.<br>— «Кедентранссервис» АҚ қызметкерлер құрамы еңбегінің төлемін реттейтін жергілікті актілерге өзгертулер және толықтырулар бекітілді.<br>— Ішкі аудит қызметінің аудиторы О. О. Макатов өкілдіктерінің тоқтатылуы туралы шешімі қабылданды.<br>— «Кедентранссервис» АҚ Ішкі аудит қызметінің аудиторы К. М. Жанагизовтың қызметтік оклады орнатылды.<br>— «Қазақстанның көліктік холдингісі» ЖШС Бақылау кеңесінің мүшесі Б. Ж. Байкариннің өкілдіктері тоқтатылды.<br>— «Қазақстанның көліктік холдингісі» ЖШС Бақылау кеңесінің жаңа мүшесі Н. Ж. Оразалин сайланды.<br>— «Қазақстанның көліктік холдингісі» ЖШС жаңа редакциядағы Есеп саясаты бекітілді.<br>— Жасалуында қызығушылық бар бірқатар мәмімелелерді жасау туралы шешімі қабылданды.' ),
		array( '26 ақпан', 'Қазақстан Республикасының Әділет министрлігі Астана қаласының Әділет департаменті сот атқарушысының «Атқарушы құжат атқарылуын қамтамасыз ету жөніндегі шараларды қабылдау туралы қаулысының күшін жою» қаулысымен 7 020 214 теңге сомасын құрайтын қаражаттарға салынған тыйым алынды.' ),
