	'2015' => array(
		array( '3 ақпан', 'Директорлар кеңесінің шешімдері:<br>1. «Кедентранссервис» АҚ жылжымалы құраммен байланысты операциялар қызметінің талдауы есепке алынды.<br>2. «Кедентранссервис» АҚ 2014 жылдың 3 тоқсанына арналған тәуекелдер тізілімінің сын тәуекелдері жөніндегі есебі бекітілді.<br>3. «Кедентранссервис» АҚ 2011–2012 жж. қаржы-шаруашылық қызметін комиссиялық тексеру барысында анықталған ескертулерді жоюға қатысты іс-шараларды атқару аудитінің қорытындылары жөніндегі есебі назарға алынды.<br>4. «Кедентранссервис» АҚ тиесілі Мүлікті мүліктен айыру ережесі жаңа редакцияда бекітілді.<br>5. «Кедентранссервис» АҚ Акцияларын шығару бағдарламасына өзгертулер мен толықтырулар енгізу үшін оларды жүзеге асырудың шаралары мен мерзімдері тізімінің өзгертулері бекітілді.<br>6. «Кедентранссервис» АҚ Бюджетті қалыптастыру және бақылау реттемесіне өзгерту мен толықтырулар бекітілді.<br>9. Жасалуында қызығушылық бар бірқатар мәмілелерді жасау туралы шешімі қабылданды.' ),
		array( '10 сәуір', 'Директорлар кеңесінің шешімдері:<br>1. «Кедентранссервис» АҚ және оның еншілес ұйымының 2014 жылға арналған қызметінің қорытындылары назарға алынды.<br>2. «Кедентранссервис» АҚ 2014 жылдың 31 желтоқсанында аяқталған жыл үшін жылдық қаржы есептілігі алдын ала бекітілді.<br>3. «Кедентранссервис» АҚ жылжымайтын мүлік объекттерін мемлекеттік тіркеу және паспорттау барысы туралы есебі назарға алынды.<br>4. «Кедентранссервис» АҚ Ішкі аудит қызметінің 2014 жылы атқарылған жұмысының есебі назарға алынды.<br>5. «Кедентранссервис» АҚ 2014 жылдың 4 тоқсанына арналған тәуекелдері тізіліміндегі сын тәуекелдер жөніндегі есебі назарға алынды.<br>6. «Кедентранссервис» АҚ Директорлар кеңесінің 2014 жылғы шешімдерін орындау жөніндегі есеп назарға алынды.<br>7. 2015 жылға арналған қаржы есептілігінің аудиты жөніндегі аудиторлық компания қызметтері төлемінің көлемі анықталды.<br>8. «Кедентранссервис» АҚ акционерлерінің жылдық жалпы жиналысын шақыру жөніндегі шешімі қабылданды.<br>9. «Кедентранссервис» АҚ Өндіріс жөніндегі вице-президентінің лауазымына кандидатура келісілді.<br>10. Басқарма мүшесі өкілдіктерінің мерзімінен бұрын аяқталуы және Басқарманың жаңа мүшесін сайлау жөніндегі шешім қабылданды.<br>11. «Кедентранссервис» АҚ Жүк және операциялық жұмысы жөніндегі Атқарушы директорының лауазымына кандидатура келісілді.<br>12. Жасалуында қызығушылық бар бірқатар мәмілелерді жасау жөніндегі шешім қабылданды.' ),
		array( '28 мамыр', 'Директорлар кеңесінің шешімдері:<br>1. «Кедентранссервис» АҚ және оның еншілес ұйымының 2015 жылдың 1 тоқсанына арналған қызметінің қорытындылары назарға алынды.<br>2. «Кедентранссервис» АҚ Директорлар кеңесінің Аудит, Стратегиялық жоспарлау және Кадрлар, сыйақылар және әлеуметтік сұрақтар комитеттер қызметтерінің қорытындыларына арналған есептері назарға алынды.<br>3. «Кедентранссервис» АҚ 2015 жылдың 1 тоқсанына арналған Тәуекелдер тізіліміндегі сын тәуекелдер жөніндегі есеп назарға алынды.<br>4. Басшылықтың, Ішкі аудит қызметі жетекшісінің және Корпоративтік хатшы тиімділігінің маңызды көрсеткіштерінің тізімдері бекітілді.<br>5. Тағайындау және босату «Кедентранссервис» АҚ Директорлар кеңесінің келісіміне жататын «Кедентранссервис» АҚ Басқару аппаратындағы қызметтердің жаңа редакциядағы тізімі бекітілді.<br>6. «Қазақстанның көліктік холдингісі» ЖШС 2014 жылға арналған жылдық қаржы есептілігі бекітілді.<br>7. «Қазақстанның көліктік холдингісі» ЖШС таза кірісін бөлу туралы шешімі қабылданды.<br>8. «Қазақстанның көліктік холдингісі» ЖШС Бас директорын сайлау туралы шешімі қабылданды.<br>9. «Қазақстанның көліктік холдингісі» ЖШС Бақылау кеңесінің мүшелерін қайта сайлау туралы шешімі қабылданды.<br>10. «Кедентранссервис» АҚ Мүддесіне қатысты дауларын реттеу жөніндегі саясаты бекітілді.<br>11. Жаңа редакцияда корпоративтік хатшы аппаратының және Ішкі аудит қызметінің еңбек төлемі және сыйақы беру жөніндегі ережесі бекітілді.<br>12. «Қазақстанның салық төлеушілері қауымдастығы» ЗТБ демеушілік көмек көрсету туралы шешімі қабылданды.<br>13. «Кедентранссервис» АҚ 2015 жылға арналған инвестициялық бағдарламасының өзгертулері келісілді.<br>14. «Кедентранссервис» АҚ Ішкі аудит қызметінің басшысы лауазымына А. Р. Сагимбаевты тағайындау туралы шешімі қабылданды.<br>15. «Алматы әуендері» Мемлекеттік коммуналдық қазыналық кәсіпорнына демеушілік көмек көрсету жөніндегі шешім қабылданды.<br>16. Жасалуында қызығушылық бар бірқатар мәмілелерді жасау туралы шешімі қабылданды.' ),
		array( '29 мамыр', 'Акционерлердің жылдық жалпы жиналысының шешімдері:<br>1. «Кедентранссервис» АҚ 2014 жылға арналған жылдық қаржы есептілігі бекітілді.<br>2. «Кедентранссервис» АҚ 2014 жылға арналған таза тізі кірісін бөлу тәртібі бекітілді.<br>3. «Кедентранссервис» АҚ 2014 жылға арналған акцияларына қатысты дивидендтердің төлемі туралы шешімі қабылданды және бір жай акцияға дивидендтің көлемі анықталды.<br>4. 2015 жылға арналған қаржы есептілігінің аудиті бойынша аудиторлық компания анықталды.<br>5. «Кедентранссервис» АҚ Жарғысына өзгертулер бекітілді.<br>6. «Кедентранссервис» АҚ Директорлар кеңесінің құрамына төмендегідей тұлғаларды сайлау туралы шешім қабылданды:<br>— Алпысбаев К.К.<br>— Баскаков П.В.<br>— Марков В.Н.<br>— Рахимбеков А.Н.<br>— Құрманов Ж.Е. (тәуелсіз директор)<br>— Дружинин А.А. (тәуелсіз директор)<br>7. «Кедентранссервис» АҚ Директорлар кеңесі мүшелерінің өкілдіктер мерзімі анықталды.<br>8. «Кедентранссервис» АҚ және оның лауазымдық тұлғаларының әрекеттеріне 2014 жылы акционерлер үндеулерінің жоқытығына қатысты, ақпарат назарға алынды.<br>9. 2014 жылы Директорлар кеңесінің мүшелері және Президент сыйақысының көлемі мен құрамы туралы, ақпарат назарға алынды.' ),
		array( '8 шілде', '«Кедентранссервис» АҚ 2014 жыл бойынша дивидендтердің төлемін бастағаны жайлы ақпараттандырады. Дивидендтерді төлеп шығу күні 2015 жылдың 7 шілдесі. Бір жай акцияға дивидендтің көлемі 947 теңге (тоғыз жүз қырық жеті) 30 тиынды құрады. Дивидендтердің төлемін жүргізу түрі – ақшалай, дивидендтердің төлемін жүргізу тәртібі – «Кедентранссервис» АҚ акционерлерінің банк шоттарына аудару арқылы ақшасыз есеп айырысу.' ),
		array( '14 шілде', '«Кедентранссервис» АҚ Директорлар кеңесінің сырттай отырысы өткізіліп, онда қызығушылығы бар бірқатар мәмілелерді жасау туралы шешімі қабылданды.<br>1. «Кедентранссервис» АҚ және «Пассажирские перевозки» АҚ филиалы «Экспресс» (атқарушы — КИО, 92–53 Сланбеков Шайхы) арасында № 106 кірме жолын мүліктік жалға алу шартын жасау туралы;<br>2. «Қазақстан темір жолы» Ұлттық компаниясы» АҚ — «Семей жол бөлімшесі» және «Кедентранссервис» АҚ Шығыс Қазақстан облысы бойынша филиалы (атқарушы — КТУ, Сухамбеков Талғат. 92–65) арасында 2015 жылға арналған Тиеу-түсіру жұмыстарын сатып алу шартын жасау туралы.' ),
		array( '4 тамыз', '«Кедентранссервис» АҚ 2014 жылға арналған өзінің жай акцияларына қатысты дивидендтердің төлемін аяқтап шықты. Бір жай акцияға шаққанда дивидендтің көлемі 947 теңге 30 тиынға теңелді.' ),
		array( '7 қыркүйек', 'Директорлар кеңесінің шешімдері:<br>— «Кедентранссервис» АҚ 2015 жылдың 30 маусымы күні аяқталған 6 айға арналған аралық шоғырландырылған қаржы есептілігі назарға алынды.<br>— «Кедентранссервис» АҚ 2013–2014 жж. және 2015 жылдың 1 жартыжылдығына арналған қаржы-шаруашылық қызметінің комиссиялық тексерісін жүргізу жоспары мен тексеру жөніндегі комиссияның жеке құрамы бекітілді.<br>— «Кедентранссервис» АҚ және оның еншілес ұйымының 2015 жылдың 1 жартыжылдығына арналған қызметінің нәтижелері жөніндегі шоғырландырылған есебі бекітілді.<br>— «Кедентранссервис» АҚ 2015 жылға арналған бюджетін түзету бекітілді.<br>— «Кедентранссервис» АҚ 2015 жылдың 1 жыртыжылдығында жүзеге асырылған сатып алулар жөніндегі есеп назарға алынды.<br>— «Кедентранссервис» АҚ жылжымайтын мүлік объекттерін мемлекеттік тіркеу барысы жайлы, ақпарат назарға алынды.<br>— «Кедентранссервис» АҚ Өндіріс жөніндегі вице-президенті Е. Р. Кулаковтың кандидатурасы келісілді.<br>— «Кедентранссервис» АҚ Басқару мүшелері — Б.О.Ағдарбекова мен Е. С. Джумасиловтың өкіділіктері мерзімінен бұрын тоқтатылып, «Кедентранссервис» АҚ Басқаруының жаңа мүшелері сайланды — Е. Р. Кулаков және М. Т. Мирзалиева.<br>— Ішкі аудит қызметінің 2015 жылдың 1 жартыжылдығында жүргізілген жұмысына қатысты есебі бекітілді.<br>— «Кедентранссервис» АҚ Ішкі аудит қызметінің аудиторы қызметіне К. М. Жанагизов тағайындалды.<br>— 9 бірлік көлемінде жұмыс істемейтін локомотив паркін жүзеге асырудың бірінші кезеңіне қатысты, ақпарат назарға алынды.<br>— «Кедентранссервис» АҚ Директорлар кеңесінің 2015 жылдың 2 тоқсанындағы шешімдерін атқару жайлы есебі назарға алынды.<br>— «Кедентранссервис» АҚ корпоративтік хатшысының қызметтік еңбекақысы анықталды.<br>— «Кедентранссервис» АҚ Корпоративтік хатшысы жөніндегі ережесіне өзгертулер мен толықтырулар бекітілді.<br>— «Кедентранссервис» АҚ корпоративтік хатшысының аппараты мен Ішкі аудит қызметінің еңбек төлемі мен сыйлықақы беру жөніндегі ережеге өзгертулер мен толықтырулар бекітлді.<br>— «Кедентранссервис» АҚ және «Қазақстанның көліктік холдингісі» ЖШС арасында 2012 жылдың 07 қыркүйегінде жасалған № 188/4-Р, Ақысыз пайдалану шартына № 5 Қосымша келісімінің жасалуы мақұлданды.<br>— «Кедентранссервис» АҚ акционерлерін шақыру және олардың кезектен тыс жалпы жиналысының күн тәртібін қалыптастыру туралы шешімі қабылданды.<br>— Жасалуында қызығушылық бар бірқатар мәмілелерді жасау туралы шешімі қабылданды.' ),
		array( '27 қазан', '«Кедентранссервис» АҚ акционерлерінің кезектен тыс жалпы жиналысы өтті. «Кедентранссервис» АҚ акционерлерінің кезектен тыс жалпы жиналысы өткізіліп, жасалуында қызығушылық бар мәміле болып табылатын «Кедентранссервис» АҚ мен «Қазақстанның көліктік холдингісі» ЖШС арасында 2012 жылдың 07 қыркүйегінде жасалған № 188/4-Р Ақысыз пайдалану шартына № 5 Қосымша келісім жасау жөніндегі шешім қабылданды.' ),
		array( '12 қараша', '«Кедентранссервис» АҚ Директорлар кеңесінің сырттай отырысы өткізіліп, оның барысында жасалуында қызығушылық бар бірқатар мәмілелерді жасау туралы шешім қабылданды.' ),
		array( '2 желтоқсан', 'Директорлар кеңесінің шешімдері:<br>— «Кедентранссервис» АҚ Директорлар кеңесінің 2015 жылдың 3 тоқсанына арналған шешімдерін атқару жөніндегі есеп назарға алынды;<br>— «Кедентранссервис» АҚ Стратегиялық жоспарлау комитетінің мүшесі сайланды;<br>— Тараптардың келісімі бойынша Еңбек келісімшартының бұзылуына орай, Экономика жөніндегі атқарушы директоры Б.О.Ағдарбекованы қызметінен босату келісілді;<br>— Тараптардың келісімі бойынша Еңбек келісімшартының бұзылуына орай, Құқықтық және мүліктік қатынастар жөніндегі атқарушы директоры Б. Ж. Байкаринді қызметінен босату келісілді;<br>— «Кедентранссервис» АҚ басшылығына сыйлықақы беру жөніндегі Ережесіне өзгертулер бекітілді;<br>— «Кедентранссервис» АҚ әкімшілік-басқару қызметкерлеріне сыйлықақы беру жөніндегі Ережесіне өзгертулер бекітілді;<br>— «Кедентранссервис» АҚ Корпоративтік хатшысы тиімділігінің басты көрсеткіштерінің 2016 жылға арналған тізімі бекітілді;<br>— «Кедентранссервис» АҚ Ішкі аудит қызметінің 2016 жылға арналған жылдық аудиторлық жоспары бекітілді;<br>— «Кедентранссервис» АҚ Ішкі аудит қызметі басшысы тиімділігінің басты көрсеткіштерінің 2016 жылға арналған тізімі бекітілді;<br>— «Кедентранссервис» АҚ Стратегиялық жоспарлау жөніндегі комитетінің мүшелеріне сыйлықақы мен қарымақы төлеу жөніндегі ережесіне, «Кедентранссервис» АҚ Аудит жөніндегі комитеті мүшелеріне сыйлықақы мен қарымақы төлеу жөніндегі ережесіне және «Кедентранссервис» АҚ Кадрлар, сыйлықақылар және әлеуметтік сұрақтар жөніндегі комитеті мүшелеріне сыйлықақы мен қарымақы төлеу жөніндегі ережесіне өзгертулер мен толықтырулар бекітілді;<br>— «Кедентранссервис» АҚ Экономика жөніндегі вице-президентінің лауазымына М. Т. Мирзалиевтің кандидатурасы келісілді;<br>— «Астана қаласы өнер академиясы» ЖШС-не демеушілік көмек көрсетілді.' ),
	),
	'2014' => array(
		array( '24 ақпан', '«Кедентранссервис» АҚ акционерлерінің кезектен тыс жалпы жиналысының шешімі:<br>2014 жылғы 24 ақпанда "Кедентранссервис" АҚ акционерлерінің кезектен тыс жалпы жиналысы өтті, онда "Кедентранссервис "АҚ Директорлар кеңесі мүшелерінің өкілеттік мерзімін ұзарту туралы" мәселе қаралып, шешім қабылданды:<br>1. Кедентранссервис " АҚ Директорлар кеңесі мүшелерінің өкілеттіктерін ұзарту»:<br>- Алпысбаев Қанат Қалиұлы<br>- Петр Васильевич Баскаков<br>— Юрий Васильевич Юрьев<br>— Марков Виктор Николаевич<br>- Рахымбеков Асқар Нұриденұлы<br>- Рымжанова Жанар Бағдатқызы<br>- Құрманов Жолдасбек Есенбайұлы (тәуелсіз директор)<br>- Резер Семен Моисеевич (тәуелсіз директор).<br>2. "Кедентранссервис" АҚ Директорлар кеңесі мүшелерінің өкілеттік мерзімі 2015 жылы акционерлердің жылдық жалпы жиналысына дейін белгіленсін.' ),
		array( '27 наурыз', 'Директорлар кеңесінің шешімдері:<br>1."Кедентранссервис" АҚ-ның, оның еншілес ұйымының 2013 жылғы қызметінің қорытындылары қаралды.<br>2."Кедентранссервис" АҚ-ның 2011-2012 жылдардағы қаржы-шаруашылық қызметіне тексеру жүргізу кезінде анықталған бұзушылықтарды жою жөніндегі іс-шаралар жоспарының орындалуы туралы есеп қаралды.<br>3.2013 жылғы 31 желтоқсанда аяқталған жыл үшін "Кедентранссервис" АҚ шоғырландырылған қаржылық есептілігі алдын ала бекітілді.<br>4."Кедентранссервис" АҚ-ның 2013 жылғы таза табысын бөлу тәртібі алдын ала бекітілді.<br>5."Кедентранссервис" АҚ акциялары бойынша 2013 жылғы дивидендтердің мөлшері алдын ала бекітілді.<br>6.2014 ж. қаржылық есептіліктің аудиті бойынша аудиторлық компания қызметтерінің төлем мөлшері анықталды.<br>7."Кедентранссервис" АҚ акционерлерінің жылдық жалпы жиналысын шақыру туралы шешім қабылданды және күн тәртібі белгіленді<br>8.Кедентранссервис "АҚ локомотив паркін оңтайландыру" жобасы бекітілді»<br>9.Кедентранссервис " АҚ қызметкерлеріне еңбекақы төлеу және еңбекке ынталандыру жүйесін реттейтін ішкі құжаттар қолданысқа енгізілді»<br>10.Кедентранссервис " АҚ тәуекелдерді басқару саясаты бекітілді»<br>11.Кедентранссервис " АҚ тәуекелдерді басқару жүйесінің тұжырымдамасы бекітілді»<br>12.Кедентранссервис " АҚ демеушілік және қайырымдылық көмек көрсету Қағидалары бекітілді»<br>13. С.Д. Аманжолов "Кедентранссервис" АҚ Ішкі аудит қызметінің басшысы лауазымына тағайындалды»<br>14. О.О. Макатов "Кедентранссервис" АҚ Ішкі аудит қызметінің аудиторы лауазымына тағайындалды»' ),
		array( '16 мамыр', '«Кедентранссервис» АҚ акционерлерінің жылдық жалпы жиналысының шешімдері:<br>2014 жылғы 16 мамырда "Кедентранссервис" АҚ акционерлерінің жылдық жалпы жиналысы өтті, онда мынадай шешімдер қабылданды:<br>1. "Кедентранссервис" АҚ-ның 2013 жылғы жылдық қаржылық есептілігі бекітілді.<br>2. "Кедентранссервис" АҚ-ның 2013 жылғы таза табысын бөлу тәртібі бекітілді.<br>3. "Кедентранссервис" АҚ акциялары бойынша 2013 жылғы дивидендтердің мөлшері бекітілді.<br>4. "Кедентранссервис" АҚ-ның 2014 жылғы қаржылық есептілігінің аудиті бойынша аудиторлық компаниясы анықталды.<br>5. "Кедентранссервис"АҚ Президенті туралы ереже бекітілді.' ),
		array( '20 мамыр', 'Жай акцияларға қатысты дивидендтердің төлемін жүргізуге қатысты хабарлама. Кедентранссервис "акционерлік қоғамы, заңды мекенжайы: 010016, Астана қ., Есіл ауданы, Достық көшесі 18; банктік деректемелері: СТН 600500054564, БСН 990840000825, БСК SABRKZKA, ЖСК KZ92914398416ВС04606" Сбербанк РОССИИ "АҚ еншілес банкінің филиалында (бұдан әрі — қоғам) жай акциялар бойынша дивидендтер төленгені туралы хабарлайды. 2013 жыл.<br>Бір жай акцияға шаққандағы дивидендтің мөлшері 767 теңге 63 тиынды құрайды.<br>Дивидендтерді төлеудің басталу күні — 2014 жылғы 17 мамыр.<br>Дивидендтерді төлеу тәртібі-Қоғам акционерлерінің банктік шоттарына аудару жолымен қолма-қол ақшасыз есеп айырысу.<br>Дивидендтерді төлеу нысаны — ақшалай.' ),
		array( '28 мамыр', 'Директорлар кеңесінің шешімдері:<br>1. "Кедентранссервис" АҚ мен оның еншілес ұйымының 2014 жылғы 1 тоқсандағы қызметінің қорытындылары қаралды.<br>2. "Кедентранссервис" АҚ басқару аппараты лауазымдарының тізімі бекітілді, оларды тағайындау және босату жаңа редакциядағы "Кедентранссервис" АҚ Директорлар кеңесімен келісуге жатады.<br>3. "Кедентранссервис"АҚ басқарма аппаратының жекелеген лауазымдарына тағайындау келісілді.<br>4. "Кедентранссервис" АҚ Директорлар кеңесінің 2015 жылғы жылдық жалпы акционерлерге дейінгі кезеңге арналған жұмыс жоспары бекітілді.<br>5. "Қазақстанның көлік холдингі"ЖШС Бақылау кеңесінің құрамы бекітілді.<br>6. Жасалуына мүдделілік бар бірқатар мәмілелер жасасу туралы шешім қабылданды.' ),
		array( '27 маусым', 'Директорлар кеңесінің шешімдері:<br>Директорлар кеңесінің 27.06.2014 ж. шешімдері<br>1. "Кедентранссервис" АҚ-ның 2014 жылға арналған түзетілген инвестициялық бюджеті бекітілді.<br>2. Локомотивтердің 26,5 бірлігін іске асыру бойынша іс-шаралар жоспары қаралды.<br>3. "Кедентранссервис" АҚ Директорлар кеңесінің 2014 жылғы 1 тоқсандағы шешімдерінің орындалуы туралы есеп назарға алынды.<br>4. "Кедентранссервис"АҚ бюджетін қалыптастыру және орындалуын бақылау регламенті бекітілді.<br>5. "Кедентранссервис"АҚ мүлкін иеліктен шығару (сату) ережесіне толықтырулар бекітілді.<br>6. "Кедентранссервис" АҚ жоғары басшылығының 2014 жылға арналған тиімділігінің негізгі көрсеткіштерінің тізбесі бекітілді.<br>7. "Кедентранссервис" АҚ Корпоративтік хатшысының 2014 жылға арналған тиімділігінің негізгі көрсеткіштерінің тізбесі бекітілді.<br>8. "Қазақстанның көлік холдингі" ЖШС-нің 2013 жылғы 31 желтоқсанда аяқталған жылға жылдық қаржылық есептілігі бекітілді.<br>9. "Қазақстанның көлік холдингі" ЖШС-нің 2013 жылғы таза табысы бөлінді.<br>10. Жасалуына мүдделілік бар бірқатар мәмілелер жасасу туралы шешім қабылданды.' ),
		array( '15 шілде', '"Кедентранссервис" АҚ 2014 жылғы 15 шілдедегі жағдай бойынша өзінің жай акциялары бойынша 2013 жылға дивидендтер төлеуді аяқтады. Бір жай акцияға шаққандағы дивиденд мөлшері 767,63 теңгені құрады".' ),
